import React, { useState, useRef } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");
  const [mode, setMode] = useState("fast"); // ⚡ added

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [loading, setLoading] = useState(false);

  const summaryRef = useRef(null);

  // 🚀 HANDLE SEARCH
  const handleSearch = async () => {
    if (!disease.trim()) return alert("Enter disease");

    setLoading(true);

    try {
      console.log("Sending mode:", mode);

      const res = await fetch("http://localhost:5000/api/research", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
          mode, // ✅ IMPORTANT
        }),
      });

      const data = await res.json();

      console.log("API RESPONSE:", data);

      setSummary(data.summary || "");
      setPublications(data.publications || []);
      setTrials(data.trials || []);

      // 🔥 Auto scroll
      setTimeout(() => {
        summaryRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 200);

    } catch (err) {
      console.error(err);
      alert("Backend error");
    }

    setLoading(false);
  };

  // ⌨️ ENTER KEY
  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSearch();
  };
{

  return (
    <div className="container">
      <h1>🧠 AI Medical Assistant</h1>

      <input
        type="text"
        placeholder="Enter disease..."
        value={disease}
        onChange={(e) => setDisease(e.target.value)}
        onKeyDown={handleKeyPress}
      />

      <input
        type="text"
        placeholder="Intent (treatment, diagnosis...)"
        value={intent}
        onChange={(e) => setIntent(e.target.value)}
      />

      <input
        type="text"
        placeholder="Location"
        value={location}
        onChange={(e) => setLocation(e.target.value)}
      />

      {/* ⚡ MODE TOGGLE */}
      <div className="mode-toggle">
        <button
          className={mode === "fast" ? "active" : ""}
          onClick={() => setMode("fast")}
        >
          ⚡ Fast
        </button>

        <button
          className={mode === "deep" ? "active" : ""}
          onClick={() => setMode("deep")}
        >
          🔬 Deep
        </button>
      </div>

      <button onClick={handleSearch} disabled={loading}>
        {loading ? "Loading..." : "Search"}
      </button>

      {/* RESULT */}
      <div ref={summaryRef}>
        {summary && (
          <div className="card">
            <h2>Summary</h2>
            <p>{summary}</p>
          </div>
        )}

        {publications.length > 0 && (
          <div className="card">
            <h2>Publications</h2>
            {publications.map((p, i) => (
              <p key={i}>{p.title}</p>
            ))}
          </div>
        )}

        {trials.length > 0 && (
          <div className="card">
            <h2>Clinical Trials</h2>
            {trials.map((t, i) => (
              <p key={i}>{t.title}</p>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

  return (
    <div className="app">
      {/* LEFT PANEL */}
      <div className="sidebar">
        <h1>Curalink X</h1>
        <p>AI Medical Research Copilot</p>

        <input
          type="text"
          placeholder="e.g., Parkinson's disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="filters">
          <label>
            <input type="checkbox" defaultChecked /> Publications
          </label>
          <label>
            <input type="checkbox" defaultChecked /> Clinical trials
          </label>
          <label>
            <input type="checkbox" defaultChecked /> Risk analysis
          </label>
        </div>

        <div className="stats">
          <p>Research papers: {publications.length}</p>
          <p>Clinical trials: {trials.length}</p>
          <p>Risk confidence: 0%</p>
        </div>
      </div>

      {/* CENTER PANEL */}
      <div className="main">
        <h1>OpenAI reasoning copilot</h1>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          onKeyDown={handleKeyPress}
        />

        <button onClick={handleSearch} disabled={loading}>
          {loading ? "⏳ Thinking..." : "Send message"}
        </button>

        <div className="metadata">
          <input
            placeholder="Location"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
          />
        </div>

        {/* SUMMARY */}
        {summary && (
          <div className="summary" ref={summaryRef}>
            <h3>AI Summary</h3>

            {/* 🔥 formatted output */}


            <div className="summary-content">
        {summary.split("\n").map((line, i) => (
    <p key={i}>{line}</p>
  ))}
</div>
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div className="right">
        {/* PUBLICATIONS */}
        <div className="card">
          <h3>Research papers</h3>

          {publications.length === 0 ? (
            <p>No publication cards available yet</p>
          ) : (
            publications.map((pub, index) => (
              <div key={index} className="item">
                <h4>{pub.title}</h4>
                <p>{pub.year}</p>
                <a href={pub.link} target="_blank" rel="noreferrer">
                  View Paper
                </a>
              </div>
            ))
          )}
        </div>

        {/* TRIALS */}
        <div className="card">
          <h3>Clinical trials</h3>

          {trials.length === 0 ? (
            <p>No clinical trials matched the current filters.</p>
          ) : (
            trials.map((trial, index) => (
              <div key={index} className="item">
                <h4>{trial.title}</h4>
                <p>Status: {trial.status}</p>
              </div>
            ))
          )}
        </div>

        {/* RISK */}
        <div className="card">
          <h3>Risk analysis</h3>
          <p>Risk analysis will appear after the first evidence run.</p>
        </div>

        {/* WHAT IF */}
        <div className="card">
          <h3>What-if Analysis</h3>
          <input placeholder="e.g., Vitamin D" />
          <button>Simulate scenario</button>
        </div>
      </div>
    </div>
  );
}

export default App;
